// Normalize the incoming lead. Invalid leads (no name or phone) are dropped.
const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const name = String(b.name ?? '').trim();
  let phone = String(b.phone ?? '').replace(/\D/g, '');
  if (phone.length === 8) phone = '216' + phone; // local Tunisian number
  if (!name || phone.length < 11 || phone.length > 15) continue;
  out.push({
    json: {
      receivedAt: new Date().toISOString(),
      name: name.slice(0, 80),
      phone: '+' + phone,
      clinic: String(b.clinic ?? '').trim().slice(0, 100),
      city: String(b.city ?? '').trim().slice(0, 50),
      email: String(b.email ?? '').trim().slice(0, 100),
      source: String(b.source ?? 'site').trim().toLowerCase().slice(0, 30),
      message: String(b.message ?? '').trim().slice(0, 500),
    },
  });
}
return out;

// Score the lead and build the final row. Falls back to a template if the AI call failed.
const lead = $('Clean lead').first().json;
const ai = $input.first().json;
const aiText = ai?.content?.[0]?.text?.trim();

const firstName = lead.name.replace(/^dr\.?\s*/i, '').split(' ')[0];
const fallback = `Bonjour Dr ${firstName}, c'est Faruk de Tbibia. Merci pour votre demande ! Je peux vous montrer Tbibia en 15 minutes cette semaine. Quel créneau vous arrange ?`;
const text = aiText || fallback;

const BIG_CITIES = ['tunis', 'sfax', 'sousse', 'ariana', 'nabeul', 'monastir', 'bizerte', 'ben arous', 'la marsa'];
const WARM_SOURCES = ['chatgpt', 'google', 'referral', 'recommandation', 'demo'];
const BUYING_WORDS = /prix|tarif|démo|demo|essai|abonnement|combien/i;

let score = 0;
if (lead.clinic) score += 1;
if (BIG_CITIES.includes(lead.city.toLowerCase())) score += 1;
if (lead.email) score += 1;
if (WARM_SOURCES.includes(lead.source)) score += 1;
if (BUYING_WORDS.test(lead.message)) score += 2;

const digits = lead.phone.replace(/\D/g, '');
return [{
  json: {
    receivedAt: lead.receivedAt,
    name: lead.name,
    phone: lead.phone,
    clinic: lead.clinic,
    city: lead.city,
    email: lead.email,
    source: lead.source,
    message: lead.message,
    score,
    priority: score >= 3 ? 'chaud' : 'normal',
    status: 'nouveau',
    lastContactAt: '',
    followUps: 0,
    aiMessage: text,
    whatsappLink: `https://wa.me/${digits}?text=${encodeURIComponent(text)}`,
  },
}];

// Daily: leads never contacted after 24h, and contacted leads silent for 3+ days (max 2 follow-ups).
const DAY = 24 * 60 * 60 * 1000;
const now = Date.now();
const notContacted = [];
const toRelance = [];

for (const { json: r } of $input.all()) {
  if (!r.phone) continue;
  const status = String(r.status ?? '').toLowerCase();
  const received = Date.parse(r.receivedAt);
  const last = Date.parse(r.lastContactAt);
  const followUps = Number(r.followUps) || 0;
  if (status === 'nouveau' && now - received > DAY) notContacted.push(r);
  if (status === 'contacté' && !Number.isNaN(last) && now - last > 3 * DAY && followUps < 2) toRelance.push(r);
}
if (!notContacted.length && !toRelance.length) return [];

const relanceLink = (r) => {
  const first = String(r.name).replace(/^dr\.?\s*/i, '').split(' ')[0];
  const msg = `Bonjour Dr ${first}, je reviens vers vous au sujet de Tbibia. Voulez-vous que je vous montre comment il fonctionne avec votre cabinet ? Ça prend 15 minutes.`;
  return `https://wa.me/${String(r.phone).replace(/\D/g, '')}?text=${encodeURIComponent(msg)}`;
};
const row = (r, link) => `<li><b>${r.name}</b> (${r.clinic || '-'}, ${r.city || '-'}) ${r.priority === 'chaud' ? '<b>[CHAUD]</b>' : ''} <a href="${link}">WhatsApp</a></li>`;

let html = '';
if (notContacted.length) html += `<h3>Pas encore contactés (${notContacted.length})</h3><ul>${notContacted.map((r) => row(r, r.whatsappLink)).join('')}</ul>`;
if (toRelance.length) html += `<h3>À relancer (${toRelance.length})</h3><ul>${toRelance.map((r) => row(r, relanceLink(r))).join('')}</ul>`;
html += '<p>Pense à mettre à jour status / lastContactAt / followUps dans la feuille après chaque message.</p>';

return [{ json: { subject: `Tbibia : ${notContacted.length + toRelance.length} leads à traiter aujourd'hui`, html } }];

// Weekly: what happened over the last 7 days.
const WEEK = 7 * 24 * 60 * 60 * 1000;
const now = Date.now();
const rows = $input.all().map((i) => i.json).filter((r) => r.phone);
const thisWeek = rows.filter((r) => now - Date.parse(r.receivedAt) <= WEEK);

const countBy = (list, key) => list.reduce((acc, r) => {
  const k = String(r[key] || '-').toLowerCase();
  return { ...acc, [k]: (acc[k] || 0) + 1 };
}, {});
const table = (obj) => Object.entries(obj).sort((a, b) => b[1] - a[1]).map(([k, v]) => `<li>${k} : ${v}</li>`).join('');

const won = rows.filter((r) => String(r.status).toLowerCase() === 'client').length;
const html = `
<h2>Tbibia - rapport de la semaine</h2>
<p><b>${thisWeek.length}</b> nouveaux leads cette semaine, dont <b>${thisWeek.filter((r) => r.priority === 'chaud').length}</b> chauds.</p>
<p>Total dans la feuille : ${rows.length} leads, ${won} devenus clients (${rows.length ? Math.round((won / rows.length) * 100) : 0}%).</p>
<h3>Sources (semaine)</h3><ul>${table(countBy(thisWeek, 'source')) || '<li>aucune</li>'}</ul>
<h3>Villes (semaine)</h3><ul>${table(countBy(thisWeek, 'city')) || '<li>aucune</li>'}</ul>
<h3>Statuts (total)</h3><ul>${table(countBy(rows, 'status'))}</ul>`;

return [{ json: { subject: `Tbibia : ${thisWeek.length} leads cette semaine`, html } }];
